1	//! File-tree buffer (DESIGN.md §5.9 buffer-as-content).
2	//!
3	//! v1 status (B.1.d): a flattened, lazily-expanded tree rendered
4	//! one entry per line. `<CR>` on a directory toggles its expansion;
5	//! on a file opens that file as a new Document buffer through the
6	//! standard `:e FILE` path. Standard motions (j/k/0/$/G/gg/<C-d>/...)
7	//! navigate via the active-buffer routing in [`crate::pane`] -- the
8	//! file tree carries no special motion bindings of its own.
9	//!
10	//! The buffer is read-only (mutations error with the same
11	//! "read-only" echo as the help buffer). To make the rendered text
12	//! consume the standard rope path, we serialise the visible tree to
13	//! a [`lattice_core::Buffer`] each time the structure changes; the
14	//! same buffer feeds syntax highlighting and any future motions
15	//! that need the line text.
16	
17	use std::path::{Path, PathBuf};
18	
19	use lattice_core::Buffer;
20	use lattice_protocol::edit::Edit;
21	use lattice_protocol::position::Position;
22	
23	use crate::buffers::BufferId;
24	
25	/// One row in the rendered file tree. `depth` controls the
26	/// indentation prefix; `kind` decides whether `<CR>` toggles
27	/// expansion or opens a file.
28	#[derive(Debug, Clone)]
29	pub struct FileTreeEntry {
30	    pub path: PathBuf,
31	    pub depth: u32,
32	    pub kind: FileTreeEntryKind,
33	}
34	
35	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
36	pub enum FileTreeEntryKind {
37	    /// A directory. `expanded = true` means the renderer recurses
38	    /// into its children.
39	    Directory { expanded: bool },
40	    /// A regular file.
41	    File,
42	}
43	
44	/// One open file-tree buffer. Composes with the rest of the
45	/// editor by exposing the same `Buffer` + cursor + scroll surface
46	/// as [`crate::help::HelpBuffer`]; motions resolve through
47	/// `lattice_grammar::execute_motion_only` against [`Self::content`].
48	#[derive(Debug)]
49	pub struct FileTreeBuffer {
50	    pub id: BufferId,
51	    pub root: PathBuf,
52	    pub entries: Vec<FileTreeEntry>,
53	    pub content: Buffer,
54	    pub cursor: Position,
55	    pub scroll: usize,
56	}
57	
58	impl FileTreeBuffer {
59	    /// Build a fresh file-tree rooted at `root`. Reads the root
60	    /// directory eagerly (one level deep); subdirectories are
61	    /// lazy-loaded on expansion.
62	    pub fn open(root: impl Into<PathBuf>) -> std::io::Result<Self> {
63	        let root = root.into();
64	        let mut entries = Vec::new();
65	        // The root itself appears as the first row so the user has
66	        // a context line + can collapse the whole view by toggling
67	        // it.
68	        entries.push(FileTreeEntry {
69	            path: root.clone(),
70	            depth: 0,
71	            kind: FileTreeEntryKind::Directory { expanded: true },
72	        });
73	        let children = read_dir_sorted(&root)?;
74	        for (path, is_dir) in children {
75	            entries.push(FileTreeEntry {
76	                path,
77	                depth: 1,
78	                kind: if is_dir {
79	                    FileTreeEntryKind::Directory { expanded: false }
80	                } else {
81	                    FileTreeEntryKind::File
82	                },
83	            });
84	        }
85	        let content = render_to_buffer(&entries);
86	        Ok(Self {
87	            id: BufferId::next(),
88	            root,
89	            entries,
90	            content,
91	            cursor: Position::ZERO,
92	            scroll: 0,
93	        })
94	    }
95	
96	    /// Toggle expansion of the directory entry at `index` (1-based
97	    /// within `entries`). Children of newly-expanded directories
98	    /// are inserted right after the directory's row at depth + 1;
99	    /// closing a directory removes every entry whose depth is
100	    /// strictly greater than the closing one until depth drops
101	    /// back. No-op for non-directory rows.
102	    pub fn toggle_at(&mut self, index: usize) -> std::io::Result<()> {
103	        let Some(entry) = self.entries.get(index) else {
104	            return Ok(());
105	        };
106	        if let FileTreeEntryKind::Directory { expanded } = entry.kind {
107	            if expanded {
108	                self.collapse(index);
109	            } else {
110	                self.expand(index)?;
111	            }
112	            self.content = render_to_buffer(&self.entries);
113	        }
114	        Ok(())
115	    }
116	
117	    fn expand(&mut self, index: usize) -> std::io::Result<()> {
118	        let parent_path = self.entries[index].path.clone();
119	        let parent_depth = self.entries[index].depth;
120	        let children = read_dir_sorted(&parent_path)?;
121	        // Splice children in one position after the parent.
122	        let insert_at = index + 1;
123	        let mut new_entries: Vec<FileTreeEntry> = children
124	            .into_iter()
125	            .map(|(path, is_dir)| FileTreeEntry {
126	                path,
127	                depth: parent_depth + 1,
128	                kind: if is_dir {
129	                    FileTreeEntryKind::Directory { expanded: false }
130	                } else {
131	                    FileTreeEntryKind::File
132	                },
133	            })
134	            .collect();
135	        // Mark parent as expanded.
136	        if let FileTreeEntryKind::Directory { ref mut expanded } = self.entries[index].kind {
137	            *expanded = true;
138	        }
139	        self.entries
140	            .splice(insert_at..insert_at, new_entries.drain(..));
141	        Ok(())
142	    }
143	
144	    fn collapse(&mut self, index: usize) {
145	        let parent_depth = self.entries[index].depth;
146	        // Mark parent as collapsed.
147	        if let FileTreeEntryKind::Directory { ref mut expanded } = self.entries[index].kind {
148	            *expanded = false;
149	        }
150	        // Drop every entry after `index` whose depth is greater
151	        // than parent_depth, until we hit one that isn't.
152	        let mut end = index + 1;
153	        while end < self.entries.len() && self.entries[end].depth > parent_depth {
154	            end += 1;
155	        }
156	        self.entries.drain(index + 1..end);
157	    }
158	
159	    /// Path under the cursor -- caller decides whether to follow it
160	    /// (`<CR>` on a file) or toggle (`<CR>` on a directory).
161	    pub fn entry_at_cursor(&self) -> Option<&FileTreeEntry> {
162	        self.entries.get(self.cursor.line as usize)
163	    }
164	
165	    pub fn line_count(&self) -> u32 {
166	        self.content.line_count()
167	    }
168	
169	    /// Same shape as `HelpBuffer::move_cursor` so the active-buffer
170	    /// routing in App can drive both kinds through the same motion
171	    /// path.
172	    pub fn move_cursor(&mut self, dx: i32, dy: i32, viewport: usize) {
173	        let last_line = self.line_count().saturating_sub(1) as i32;
174	        let new_line = (self.cursor.line as i32 + dy).clamp(0, last_line) as u32;
175	        let line_len = line_byte_len(&self.content, new_line);
176	        let new_byte = (self.cursor.byte as i32 + dx).clamp(0, line_len as i32) as u32;
177	        self.cursor = Position::new(new_line, new_byte);
178	        self.adjust_scroll_to_cursor(viewport);
179	    }
180	
181	    pub fn jump_cursor_to(&mut self, line: u32, viewport: usize) {
182	        let last_line = self.line_count().saturating_sub(1);
183	        let target = line.min(last_line);
184	        let line_len = line_byte_len(&self.content, target);
185	        self.cursor = Position::new(target, self.cursor.byte.min(line_len));
186	        self.adjust_scroll_to_cursor(viewport);
187	    }
188	
189	    pub fn adjust_scroll_to_cursor(&mut self, viewport: usize) {
190	        if viewport == 0 {
191	            return;
192	        }
193	        let line = self.cursor.line as usize;
194	        if line < self.scroll {
195	            self.scroll = line;
196	        } else if line >= self.scroll + viewport {
197	            self.scroll = line + 1 - viewport;
198	        }
199	    }
200	}
201	
202	/// Read a directory's children, partitioned (directories first)
203	/// and sorted by name. Hidden files (those starting with `.`) are
204	/// included so the user can navigate config dirs; future polish
205	/// can add a toggle.
206	fn read_dir_sorted(root: &Path) -> std::io::Result<Vec<(PathBuf, bool)>> {
207	    let mut out: Vec<(PathBuf, bool)> = Vec::new();
208	    for entry in std::fs::read_dir(root)? {
209	        let entry = entry?;
210	        let path = entry.path();
211	        let is_dir = entry.file_type()?.is_dir();
212	        out.push((path, is_dir));
213	    }
214	    out.sort_by(|a, b| {
215	        // Directories before files; then alpha.
216	        match (a.1, b.1) {
217	            (true, false) => std::cmp::Ordering::Less,
218	            (false, true) => std::cmp::Ordering::Greater,
219	            _ => a.0.cmp(&b.0),
220	        }
221	    });
222	    Ok(out)
223	}
224	
225	/// Serialise the entry list to a [`Buffer`]. Each row is
226	/// `<indent><marker><name>` where `<marker>` is `▾ ` for an
227	/// expanded dir, `▸ ` for a collapsed dir, and `  ` for a file.
228	/// Indent is two spaces per `depth`. Re-rendered every time the
229	/// tree structure changes; cheap on real-sized trees (~hundreds of
230	/// rows).
231	fn render_to_buffer(entries: &[FileTreeEntry]) -> Buffer {
232	    let mut text = String::new();
233	    for (i, entry) in entries.iter().enumerate() {
234	        let indent = "  ".repeat(entry.depth as usize);
235	        let marker = match entry.kind {
236	            FileTreeEntryKind::Directory { expanded: true } => "▾ ",
237	            FileTreeEntryKind::Directory { expanded: false } => "▸ ",
238	            FileTreeEntryKind::File => "  ",
239	        };
240	        let name = if entry.depth == 0 {
241	            entry.path.display().to_string()
242	        } else {
243	            entry
244	                .path
245	                .file_name()
246	                .map(|s| s.to_string_lossy().into_owned())
247	                .unwrap_or_default()
248	        };
249	        text.push_str(&indent);
250	        text.push_str(marker);
251	        text.push_str(&name);
252	        if i + 1 < entries.len() {
253	            text.push('\n');
254	        }
255	    }
256	    let mut buffer = Buffer::empty();
257	    if !text.is_empty() {
258	        let _ = buffer.apply_edit(&Edit::insert(Position::ZERO, text));
259	    }
260	    buffer
261	}
262	
263	fn line_byte_len(buf: &Buffer, line: u32) -> u32 {
264	    let s = buf.as_string();
265	    s.split('\n')
266	        .nth(line as usize)
267	        .map(|l| l.len() as u32)
268	        .unwrap_or(0)
269	}
