3	use std::path::Path;
4	use ratatui::style::{Color, Style};
5	
6	use crate::theme::Theme;
7	
8	/// Returns `(glyph, style)` for a directory or file entry.
9	/// When `nerd_fonts` is false the glyph is `""` (no column rendered)
