fn render_to_buffer(entries: &[FileTreeEntry], nerd_fonts: bool) -> Buffer {
    use crate::icons::icon_for_entry;
    use crate::theme::Theme;
    let theme = Theme::default();
    let mut text = String::new();
    for (i, entry) in entries.iter().enumerate() {
